WITH store_discount AS ( SELECT ss.ss_sold_date_sk AS sold_date_sk, ss.ss_customer_sk AS customer_sk, cd.cd_gender, ss.ss_ext_discount_amt AS discount_amt, PERCENT_RANK() OVER (PARTITION BY cd.cd_gender ORDER BY ss.ss_ext_discount_amt) AS discount_percentile FROM store_sales ss JOIN customer_demographics cd ON ss.ss_cdemo_sk = cd.cd_demo_sk ), web_discount AS ( SELECT ws.ws_sold_date_sk AS sold_date_sk, ws.ws_bill_customer_sk AS customer_sk, cd.cd_gender, ws.ws_ext_discount_amt AS discount_amt, PERCENT_RANK() OVER (PARTITION BY cd.cd_gender ORDER BY ws.ws_ext_discount_amt) AS discount_percentile FROM web_sales ws JOIN customer_demographics cd ON ws.ws_bill_cdemo_sk = cd.cd_demo_sk ) SELECT * FROM ( SELECT 'store' AS channel, sd.sold_date_sk, sd.customer_sk, sd.cd_gender, sd.discount_amt, sd.discount_percentile, CASE WHEN sd.discount_percentile > 0.75 THEN 1 ELSE 0 END AS high_discount_flag FROM store_discount sd UNION ALL SELECT 'web' AS channel, wd.sold_date_sk, wd.customer_sk, wd.cd_gender, wd.discount_amt, wd.discount_percentile, CASE WHEN wd.discount_percentile > 0.75 THEN 1 ELSE 0 END AS high_discount_flag FROM web_discount wd ) combined WHERE high_discount_flag = 1 ORDER BY channel, discount_percentile DESC LIMIT 100
